mapper.select:
SELECT
,ui.id as info_id,ui.first_name,ui.last_name,sf.file_url AS avatar_url,sf.save_type FROM gc_user_answer AS ua LEFT JOIN gc_user AS u ON u.id=ua.user_id LEFT JOIN gc_user_info ui on ui.id=u.info_id LEFT JOIN sys_file f on ui.avatar_file_id=f.id LEFT JOIN sys_file AS sf ON sf.id = ui.avatar_file_id WHERE ua.event_id=#{eventId} and ua.master_id=#{masterId}
and ua.user_id !=#{userId}

SELECT COUNT(id) AS answerNum, TO_CHAR(update_time, 'YYYY-MM-DD') AS update_time FROM gc_user_answer ua WHERE user_id in
#{userId}
AND TO_CHAR(update_time, 'YYYY-MM-DD') >= #{startDate} AND TO_CHAR(update_time, 'YYYY-MM-DD') <= #{endDate} GROUP BY TO_CHAR(update_time, 'YYYY-MM-DD')

SELECT * from gc_user_answer answer left join gc_event e on e.id=answer.event_id where event_id in
#{eventId}
and answer.master_id=#{masterId} or(e.upload_type != #{type} and answer.user_id=#{userId})

SELECT * from gc_user_answer answer
left join gc_event e on e.id=answer.event_id
where event_id in

    #{eventId}

and answer.master_id=#{masterId} and answer.user_id = #{userId}

select * from gc_user_answer answer
LEFT JOIN gc_event event on event.id = answer.event_id
LEFT JOIN gc_video video on video.id = event.video_id
LEFT JOIN gc_subject sub1 on sub1.id = video.sub_id
LEFT JOIN gc_subject sub0 on sub0.id = sub1.fid
where answer.user_id=#{userId} and answer.master_id=#{masterId}

    and video.id=#{videoId}


    and sub0.id=#{sub0Id}


    and sub1.id=#{sub1Id}
